class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        n = s_cnt = e = w = 0
        ans = 0

        for i, ch in enumerate(s, 1):
            if ch == 'N':
                n += 1
            elif ch == 'S':
                s_cnt += 1
            elif ch == 'E':
                e += 1
            else:
                w += 1

            # Minimum bad moves across all 4 possible quadrants
            min_bad = min(n, s_cnt) + min(e, w)

            # Distance if we convert up to `k` bad moves to good moves
            val = i - 2 * max(0, min_bad - k)
            if val > ans:
                ans = val

        return ans
